using Avalonia;
using System;

namespace {{ProjectNameIdentifier}};

internal static class Program
{
    [STAThread]
    public static void Main(string[] args)
    {
        BuildAvaloniaApp().StartWithClassicDesktopLifetime(args);
    }

    public static AppBuilder BuildAvaloniaApp()
    {
        return AppBuilder.Configure<App>()
            .UsePlatformDetect()
            .WithInterFont()
            .LogToTrace();
    }
}

using Avalonia;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Markup.Xaml;
using {{ProjectNameIdentifier}}.ViewModels;
using {{ProjectNameIdentifier}}.Views;

namespace {{ProjectNameIdentifier}};

public partial class App : Application
{
    public override void Initialize()
    {
        AvaloniaXamlLoader.Load(this);
    }

    public override void OnFrameworkInitializationCompleted()
    {
        if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)
        {
            desktop.MainWindow = new MainWindow
            {
                DataContext = new MainWindowViewModel(),
            };
        }

        base.OnFrameworkInitializationCompleted();
    }
}

using Avalonia.Controls;

namespace {{ProjectNameIdentifier}}.Views;

public partial class MainWindow : Window
{
    public MainWindow()
    {
        InitializeComponent();
    }
}

using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using {{ProjectNameIdentifier}}.Models;

namespace {{ProjectNameIdentifier}}.ViewModels;

public partial class MainWindowViewModel : ObservableObject
{
    public MainWindowViewModel()
    {
        Name = string.Empty;
        Greeting = "Enter a name and choose Greet.";
    }

    [ObservableProperty]
    public partial string Name { get; set; }

    [ObservableProperty]
    public partial string Greeting { get; set; }

    [RelayCommand]
    private void Greet()
    {
        Greeting = GreetingMessage.Create(Name);
    }
}

namespace {{ProjectNameIdentifier}}.Models;

public static class GreetingMessage
{
    public static string Create(string name)
    {
        return string.IsNullOrWhiteSpace(name)
            ? "Please enter a name first."
            : $"Hello, {name}!";
    }
}
